SELECT credit_limit_bucket, stddev_credit_limit, min_credit_limit FROM (SELECT CASE WHEN credit_limit >= 17900 THEN 'high' WHEN credit_limit >= 8000 THEN 'mid' ELSE 'low' END AS credit_limit_bucket, ROUND(STDDEV(credit_limit), 2) AS stddev_credit_limit, MIN(credit_limit) AS min_credit_limit FROM customers WHERE city = 'Bangkok' GROUP BY CASE WHEN credit_limit >= 17900 THEN 'high' WHEN credit_limit >= 8000 THEN 'mid' ELSE 'low' END) AS x WHERE stddev_credit_limit > 46;
